<template><span class="prose"><template v-for="(part,i) in parts" :key="i"><router-link v-if="part.id" :to="'/characters/'+part.id" class="character-themed character-name character-mention" :style="characterTheme((characters||[]).find(c=>c.id===part.id))">@{{part.text}}</router-link><template v-else>{{part.text}}</template></template></span></template>
<script setup>import {computed} from 'vue';import {characterTheme} from './character-theme.mjs';import {mentionParts} from './domain.mjs';const props=defineProps({text:String,characters:Array});const parts=computed(()=>mentionParts(props.text,props.characters||[]));</script>
